std::string_view GetOpcodeName(uint16 opcode)
{
    if (char const* name = Admin::EnumNameOpcode(Admin::Opcode(opcode)); *name)
        return name;
    return Reader::EnumNameOpcode(Reader::Opcode(opcode));
}

std::span<ApiOperation const> GetApiOperations()
{
    return Operations;
}

ApiOperation const* FindApiOperation(uint16 opcode)
{
    auto itr = std::ranges::find(Operations, opcode, [](ApiOperation const& operation) { return operation.Opcode.Value; });
    return itr != std::end(Operations) ? &*itr : nullptr;
}

ApiOperation const& GetApiOperation(ApiOp op)
{
    auto itr = std::ranges::find(Operations, op, &ApiOperation::Op);
    ASSERT(itr != std::end(Operations), "An ApiOp without its row in ApiOperations.cpp");
    return *itr;
}
